{
  "histories": [
    {
      "person": "Spencer Navarro",
      "changes": [
        {
          "topic": "Presence at Allied Wholesale Pharmacy Depot on the night of 2019-05-16",
          "earlier_quote": "I was in Osage County playing cards with friends from 20:30 until 01:15 and never drove anywhere near Allied Wholesale Pharmacy Depot on 2019-05-16.",
          "earlier_doc": "doc07",
          "later_quote": "After reviewing the toll record, I admit I drove my gold 2008 Kia Sedona to the Allied Wholesale Pharmacy Depot lot around 23:02 to discuss our financial dispute. The vault control office window looked dark behind the blinds, nobody answered, so I pulled out by 23:14, crossed Bypass 50 back into Osage County, and fueled at the cardlock pump at 23:36.",
          "later_doc": "doc08"
        }
      ]
    },
    {
      "person": "Lucia Carver",
      "changes": [
        {
          "topic": "Departure timing and whether victim exited office to speak near supply alcove",
          "earlier_quote": "I clocked out at 22:15, called goodnight to Camille Khoury through the closed vault control office door while Camille worked inside, and drove straight home before 22:50.",
          "earlier_doc": "doc12",
          "later_quote": "I left around 22:00, maybe ten past, and I stopped by the supply alcove where Camille Khoury stepped out of the vault control office to talk for a minute about Tuesday's schedule before I headed home.",
          "later_doc": "doc13"
        }
      ]
    }
  ],
  "next_questions": [
    {
      "person": "Gregory Guzman",
      "question": "Your logbook notes checking the vault control office door at 00:07 while doc05 records master PIN 9039 unlocking the strike at 00:07; why was your master PIN entered if you only checked the handle from the corridor?",
      "anchored_quote": "2019-05-17 00:07 — PIN 9039 UNLOCK",
      "doc_id": "doc05"
    },
    {
      "person": "Lucia Carver",
      "question": "In 2019 you stated you called goodnight through the closed door at 22:15, whereas in 2025 you recalled speaking with Camille Khoury outside the supply alcove around 22:00; what prompted that added recollection?",
      "anchored_quote": "I left around 22:00, maybe ten past, and I stopped by the supply alcove where Camille Khoury stepped out of the vault control office to talk for a minute about Tuesday's schedule before I headed home.",
      "doc_id": "doc13"
    },
    {
      "person": "Spencer Navarro",
      "question": "When you parked in the Allied Wholesale Pharmacy Depot lot between 22:56 and 23:18 before crossing back to fuel at 23:36, did you see any other vehicles or movement near the vault control office corridor?",
      "anchored_quote": "After reviewing the toll record, I admit I drove my gold 2008 Kia Sedona to the Allied Wholesale Pharmacy Depot lot around 23:02 to discuss our financial dispute. The vault control office window looked dark behind the blinds, nobody answered, so I pulled out by 23:14, crossed Bypass 50 back into Osage County, and fueled at the cardlock pump at 23:36.",
      "doc_id": "doc08"
    },
    {
      "person": "Preston Benitez",
      "question": "When you unlocked the vault control office with PIN 7551 at 22:48, were the window blinds already drawn shut and did the door latch catch when you exited?",
      "anchored_quote": "I returned to Allied Wholesale Pharmacy Depot around 22:48 and keyed my own PIN 7551 at the vault control office door to pick up my keys. Camille Khoury was seated at the desk alive doing end-of-shift reconciliation. I stayed two minutes and drove straight home by 23:25.",
      "doc_id": "doc06"
    }
  ]
}

